]},
{"clause_id": "c049", "issues": [
  {"issue": null, "type": 1, "prob": 0.19},
  {"issue": "The cap on Loan Services compensation is measured by fees \"payable pursuant to paragraphs 5.4(b)-(f)\", yet 5.4 states those fees are payable to the Manager or its designee, not necessarily to the Servicer, and 5.6 lets Affiliates keep further compensation outright. Whether the cap is effective is arguable.", "type": 2, "prob": 0.29}
